import { lazy, Suspense, useCallback, useEffect, useRef, useState } from 'react';
import { LazyMotion, MotionConfig } from 'motion/react';
import type { LineId } from './data/types';
import { Nav } from './components/Nav';
import { Footer } from './components/Footer';
import { Hero } from './components/Hero';
import { Register } from './components/Register';
import { Finding } from './components/Finding';
import { Examines } from './components/Examines';
import { Campaign } from './components/Campaign';
import { useSmoothScroll } from './components/fx';
import { Movement } from './components/Movement';
import { Question } from './components/Question';
import { Numbers } from './components/Numbers';
import { Economics } from './components/Economics';
import { Locker } from './components/Locker';
import { Limits } from './components/Limits';
import { Finale } from './components/Finale';
import { rowByAnchor, site } from './lib/site';
import { MAIN_CLASS } from './lib/layout';

const Receipt = lazy(() => import('./components/Receipt'));
const motionFeatures = () => import('./lib/motion-features').then((m) => m.default);
const DEFAULT_LINE = site.lines[0]!.id;

const fromHash = () => {
  const h = decodeURIComponent(window.location.hash.slice(1));
  return rowByAnchor.has(h) ? h : null;
};

export default function App() {
  const [anchor, setAnchor] = useState<string | null>(fromHash);
  const [line, setLine] = useState<LineId>(DEFAULT_LINE);
  const [everOpened, setEverOpened] = useState(Boolean(anchor));
  const trigger = useRef<HTMLElement | null>(null);
  useSmoothScroll();

  useEffect(() => {
    const sync = () => {
      const h = fromHash();
      // a plain #HL-4.2-… link (Fig. 2, Method) opened it: return focus there on close
      if (h && document.activeElement instanceof HTMLElement && document.activeElement !== document.body)
        trigger.current = document.activeElement;
      setAnchor(h);
      if (h) setEverOpened(true);
    };
    window.addEventListener('hashchange', sync);
    window.addEventListener('popstate', sync);
    return () => {
      window.removeEventListener('hashchange', sync);
      window.removeEventListener('popstate', sync);
    };
  }, []);

  const open = useCallback((a: string, l: LineId, el: HTMLElement | null) => {
    trigger.current = el;
    setLine(l);
    setAnchor(a);
    setEverOpened(true);
    history.pushState(null, '', `#${a}`);
  }, []);

  const close = useCallback(() => {
    setAnchor(null);
    if (window.location.hash) history.pushState(null, '', window.location.pathname + window.location.search);
  }, []);

  const returnFocus = useCallback(() => {
    const el = trigger.current;
    if (el && document.contains(el)) el.focus();
    else document.getElementById('register')?.querySelector<HTMLElement>('button[tabindex="0"]')?.focus();
  }, []);

  return (
    <MotionConfig reducedMotion="user">
      <LazyMotion features={motionFeatures} strict>
        <a
          href="#main"
          className="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-3 focus:z-50 focus:rounded-full focus:bg-brass focus:px-4 focus:py-2 focus:text-paper"
        >
          Skip to the record
        </a>
        <Nav />
        <main id="main" className={MAIN_CLASS}>
          <Hero />
          <Examines />
          <Campaign />
          <Finding />
          <Register onOpen={open} />
          <Movement />
          <Question />
          <Numbers />
          <Economics />
          <Locker />
          <Limits />
          <Finale />
        </main>
        <Footer generatedAt={site.generated_at} />
        {everOpened && (
          <Suspense fallback={null}>
            <Receipt
              row={anchor ? rowByAnchor.get(anchor) ?? null : null}
              line={line}
              onLine={setLine}
              onClose={close}
              returnFocus={returnFocus}
            />
          </Suspense>
        )}
      </LazyMotion>
    </MotionConfig>
  );
}
// QA loop (brief §6): screenshots, keyboard flow, axe, console, Lighthouse, budgets.
// Usage: npm run build && node scripts/qa.mjs <cycle>   → qa/<cycle>/ (git-ignored)
import { spawn, execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { gzipSync } from 'node:zlib';
import { chromium } from 'playwright';
import { AxeBuilder } from '@axe-core/playwright';

const WEB = new URL('..', import.meta.url).pathname;
const cycle = process.argv[2] ?? 'c1';
const OUT = join(WEB, 'qa', cycle);
mkdirSync(OUT, { recursive: true });
const PORT = +(process.env.PORT ?? 4300);
const URL_ = `http://localhost:${PORT}/`;
const report = { cycle, at: new Date().toISOString(), screenshots: [], axe: [], console: [], keyboard: null, lighthouse: null, budgets: null };

// ---------- serve dist ----------
const server = spawn(process.execPath, [`${WEB}node_modules/vite/bin/vite.js`, 'preview', '--port', String(PORT), '--strictPort'], { cwd: WEB, stdio: 'pipe' });
const stop = () => server.kill('SIGTERM');
process.on('exit', stop);
for (let i = 0; i < 60; i++) {
  try {
    const r = await fetch(URL_);
    if (r.ok) break;
  } catch {
    /* not up yet */
  }
  await new Promise((r) => setTimeout(r, 250));
}

// SwiftShader WebGL so the lazy 3D hero actually mounts headless
const browser = await chromium.launch({ args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const VIEWPORTS = [
  [390, 844],
  [768, 1024],
  [1440, 900],
  [1920, 1080],
];

async function page(opts = {}) {
  const ctx = await browser.newContext({
    viewport: { width: opts.w ?? 1440, height: opts.h ?? 900 },
    colorScheme: opts.scheme ?? 'dark',
    reducedMotion: opts.reduced ? 'reduce' : 'no-preference',
    deviceScaleFactor: 1,
  });
  const p = await ctx.newPage();
  const tag = `${opts.w ?? 1440}x${opts.h ?? 900}${opts.reduced ? '-reduced' : ''}`;
  p.on('console', (m) => {
    if (m.type() === 'error' || m.type() === 'warning') report.console.push({ tag, type: m.type(), text: m.text() });
  });
  p.on('pageerror', (e) => report.console.push({ tag, type: 'pageerror', text: String(e) }));
  await p.goto(URL_ + (opts.hash ?? ''), { waitUntil: 'networkidle' });
  await p.evaluate(() => document.fonts.ready);
  return { p, ctx, tag };
}
// scroll the whole page once so every once-only in-view reveal has fired before a full-page shot
async function warm(p) {
  await p.evaluate(async () => {
    const H = document.documentElement.scrollHeight;
    for (let y = 0; y < H; y += Math.round(innerHeight * 0.6)) {
      window.scrollTo(0, y);
      await new Promise((r) => setTimeout(r, 120));
    }
    window.scrollTo(0, 0);
    await new Promise((r) => setTimeout(r, 1600));
  });
}
const scrollToEl = (p, sel, frac = 0) =>
  p.evaluate(
    async ([sel, frac]) => {
      const el = document.querySelector(sel);
      const top = el.getBoundingClientRect().top + scrollY;
      window.scrollTo(0, top + (el.offsetHeight - (frac ? innerHeight : 0)) * frac);
      await new Promise((r) => setTimeout(r, 1500));
    },
    [sel, frac],
  );
const shot = async (p, name, full = true) => {
  const path = join(OUT, `${name}.png`);
  await p.screenshot({ path, fullPage: full });
  report.screenshots.push(`${name}.png`);
};
async function axe(p, tag) {
  const r = await new AxeBuilder({ page: p }).withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa', 'best-practice']).analyze();
  const bad = r.violations.filter((v) => v.impact === 'serious' || v.impact === 'critical');
  report.axe.push({
    tag,
    serious_or_critical: bad.length,
    violations: r.violations.map((v) => ({ id: v.id, impact: v.impact, nodes: v.nodes.length, sample: v.nodes[0]?.target })),
  });
}

// ---------- screenshots (+ axe on each) ----------
for (const [w, h] of VIEWPORTS) {
  const { p, ctx, tag } = await page({ w, h });
  // the v2 page is ~30 000 px tall: no full-page shots (software rendering stalls); the beats are shot below
  await shot(p, `first-${tag}`, false);
  await warm(p);
  await axe(p, tag);
  await ctx.close();
}

// ---------- v2 beats in the viewport: hero with the live 3D, campaign middle, movement, finale ----------
for (const [w, h] of [[1440, 900], [390, 844]]) {
  const { p, ctx, tag } = await page({ w, h });
  const live = await p
    .waitForSelector('[data-poster="hero"].opacity-0', { state: 'attached', timeout: 60_000 })
    .then(() => true, () => false);
  report[`hero_3d_${w}`] = live;
  await p.waitForTimeout(1200);
  await shot(p, `hero-${tag}`, false);
  await scrollToEl(p, '#watch', 0.5);
  await shot(p, `campaign-mid-${tag}`, false);
  await scrollToEl(p, '#movement > div', 0.6);
  await shot(p, `movement-${tag}`, false);
  for (const id of ['#question', '#numbers', '#economics', '#evidence']) {
    await scrollToEl(p, id);
    await p.waitForTimeout(900);
# Hero 3D movement: look-development notes

Screenshots from `three-demo.html?still=1&text=1` at 1600×1000 (headless Chromium, SwiftShader WebGL),
with a placeholder headline on the left to judge the negative space.

## Iteration 1
- **Composition:** far too close. The train fills the frame edge to edge and the upper-left wheel sits
  behind the headline; there is no negative space on the left.
- **Brass:** reads as flat yellow "gold", not brass. RoomEnvironment at full intensity reflects a bright,
  even grey room into every metal face, so there is no contrast between faces and bevels.
- **Wheels:** module 0.075 gives chunky, few teeth; it reads as a clip-art cog, not a watch wheel.
- **Medallion:** guilloché bump too faint and the face too pale; the "H" is fine but lacks polish.
- **Bevels:** too small to catch light.
- What works: the meshing is correct (teeth interleave), the deep-brass variant on two wheels adds depth,
  the ruby jewels and steel collets are a believable detail.

**Changes →** module 0.055 with tooth counts scaled up (110/28/64/40/22/48/32), wider bevels, steel
10-leaf pinions on every arbor, environment intensity 0.9 → 0.5, stronger warm key + a cool rim light,
camera pulled back with a lens shift (`filmOffset`) so the movement sits in the right two thirds with
perspective unchanged, deeper medallion colour, stronger bump.

## Iteration 2
- **Composition:** the left is now clean for the headline, but the cluster hugs the right edge and is
  cropped on two sides; it feels pushed off rather than placed.
- **Brass:** still low dynamic range. A directional key lights a flat face uniformly, so every top face
  has the same value; nothing reads as a polished highlight sweeping across metal.
- **Medallion:** the second family of curved radial strokes makes the rosette look hairy (a fingerprint),
  not the crisp moiré lattice of a rose-engine cut.
- What works: finer teeth and steel pinions immediately read as horology; the jewel + collet + pinion
  stack gives each arbor scale.

**Changes →** the key light becomes a warm point light behind and above the train (`decay 2`), so each
flat face carries a falloff and the specular sweeps across the metal as the wheels turn and the pointer
tilts the rig; the directional light drops to a fill. The rosette loses the radial family and becomes
44 thinner rings with a 0.28 rad phase step per ring (a clean barleycorn moiré). A main plate is added
under the train: dark gilt (#3A3022) with a canvas perlage bump and a deep-brass bevelled edge, with the
ContactShadow just above it so wheels sit on something.

## Iteration 3
- **Big step up.** The plate turns floating cogs into a movement; brass now has real value range
  (bright bevels on the centre wheel's rim, darker faces away from the key).
- **Composition:** the plate (r 7.6) is too large; its edge runs behind "software" and "honest".
- **Highlights:** the point light reflects in the medallion's clearcoat as a small blown-out white disc,
  which reads as a cheap lens flare, not a studio softbox.
- **Steel:** pinions are too white and bright, like chrome plastic toys next to the brass.
- **Perlage:** too regular at bumpScale 1.2; reads as a woven pattern.

**Changes →** plate r 6.1 moved right, perlage bump halved, steel darkened (#8F9296, roughness 0.24),
pinions thinner, medallion clearcoat 0.35 / clearcoat roughness 0.3, key light moved further back-left.

## Iteration 4
- The hotspot is gone; the medallion reads as engraved, satin-clearcoated brass with a polished cartouche
  and a crisp raised serif H. Pinions now read as grey steel and give scale.
- **Composition:** the plate's edge still kisses the comma of "software,"; the upper-left wheel
  half-overhangs the plate edge, which looks accidental.

**Changes →** plate nudged right/back; that wheel moved to 1.65 rad around the centre wheel (checked
for clearance against the 40-tooth wheel: tip circles 2.95 apart vs 2.53 needed).

## Iteration 5 (shipped)

