  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Heirloom — 3D movement demo</title>
    <meta name="robots" content="noindex" />
    <style>
      html, body { margin: 0; background: #08090A; }
    </style>
  </head>
  <body>
    <div id="root"></div>
    <script type="module" src="/src/three/demo.tsx"></script>
  </body>
</html>

